import { Img, useCurrentFrame, useVideoConfig, interpolate } from "remotion";

interface NewsCoverProps {
  /** HTTP(S) URL of the generated 1080x1920 cover PNG. */
  src: string;
  /** Seconds the cover stays on screen at the very start of the video. */
  coverSec: number;
}

/**
 * Embedded thumbnail / title card: the first `coverSec` seconds of a
 * news-style video show a full-bleed cover (face-centered speaker frame +
 * oversized hook text, generated by scripts/make_cover.py) so the reel
 * cover Facebook picks from the video frames is always strong — no manual
 * cover selection in the app needed.
 *
 * The content (video + captions) is delayed behind it via a <Sequence> in
 * ShortVideo, so the cover never eats into the teaser.
 */
export const NewsCover: React.FC<NewsCoverProps> = ({ src, coverSec }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  if (!src || coverSec <= 0 || frame / fps >= coverSec) return null;

  // Gentle settle zoom so the still feels alive
  const progress = interpolate(frame, [0, coverSec * fps], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const scale = 1.045 - 0.045 * progress;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor: "black",
        pointerEvents: "none",
      }}
    >
      <Img
        src={src}
        style={{
          width: 1080,
          height: 1920,
          objectFit: "cover",
          transform: `scale(${scale})`,
        }}
      />
    </div>
  );
};
